#include <string>
class pupil_Type {
private:
    std::string str_student_name;
public:
    /* Function Objective: Store the name of a student
       Input parameters : str_new_name (string) the new student name
       Function description: Keep the new name, shortened to the maximum name size when it is too long
       Return Value : void
       Created By : Programmer A
       Create Date: 2026-09-28
       Revised By:
       Revised Date:
    */
    void Set_Name(std::string str_new_name) {
        const int MAX_NAME_SIZE = 30;
        bool isLong = str_new_name.size() > MAX_NAME_SIZE;
        // check whether the name must be shortened
        if (isLong) {
            str_student_name = str_new_name.substr(0, MAX_NAME_SIZE);
        }
        // else the name fits, keep it
        else {
            str_student_name = str_new_name;
        }
    }
};
